 By the triangle inequality, the error can be split as
\[
\|\boldsymbol{x}(p_*) - \boldsymbol{p}_R(p_*)\|_2 \le \|\boldsymbol{x}(p_*) - \boldsymbol{x}_R(p_*)\|_2 + \|\boldsymbol{x}_R(p_*) - \boldsymbol{p}_R(p_*)\|_2.
\]
We divide the proof into two cases.

\noindent\textbf{Case 1: $\boxed{p_* \in [-1,1]}$.}
Since $p_* \in [-1,1]$, the Chebyshev polynomials satisfy $|T_k(p_*)| \le 1$ for all $k \ge 0$. It holds that
\[
\|\boldsymbol{x}(p_*) - \boldsymbol{x}_R(p_*)\|_2 \le \sum_{k=R+1}^\infty \|\boldsymbol{c}_k\|_2 |T_k(p_*)| \le 2\kappa_\rho \sum_{k=R+1}^\infty \rho^{-k} = \frac{2\kappa_\rho}{1 - \rho^{-1}} \rho^{-(R+1)}.
\]
For the second term,  we have:
\[
\|\boldsymbol{x}_R(p_*) - \boldsymbol{p}_R(p_*)\|_2 = \|(C_x - C_p)\boldsymbol{q}_R(p_*)\|_2 \le \|C_x - C_p\|_2 \|\boldsymbol{q}_R(p_*)\|_2.
\]
and we can substitute \eqref{eq: cxcp} and $\|\boldsymbol{q}_R(p_*)\|_2 = \sqrt{\sum_{k=0}^R |T_k(p_*)|^2} \le \sqrt{R+1}.$

\noindent\textbf{Case 2: $\boxed{p_* \in \left(1, \frac{\rho + \rho^{-1}}{2}\right)}$.} Outside the interval $[-1,1]$, the growth of the Chebyshev polynomials is bounded by $|T_k(p_*)| \le (\rho \delta)^k$, where $\delta = \frac{p_* + \sqrt{p_*^2 - 1}}{\rho} < 1$~\cite{mason2010chebyshev}. Consequently:
\[
\|\boldsymbol{q}_R(p_*)\|_2 = \sqrt{\sum_{k=0}^R |T_k(p_*)|^2} \le \sqrt{\sum_{k=0}^R (\rho\delta)^{2k}} = \sqrt{\frac{(\rho\delta)^{2(R+1)} - 1}{\rho^2\delta^2 - 1}} < \frac{(\rho\delta)^{R+1}}{\sqrt{\rho^2\delta^2 - 1}}.
\]

By applying this bound to the same error splitting we obtain the second inequality of the theorem.

