\min_{\boldsymbol{c}} \|B\boldsymbol{c} - \boldsymbol{b}\|_2 
\qquad\text{and}\qquad
\min_{\hat{\boldsymbol{c}}} \|S(B\hat{\boldsymbol{c}} - \boldsymbol{b})\|_2,
\]
where $S \in \mathbb{R}^{s \times n}$ with $r \le s \le n$.
Then we have
\begin{equation}
1\leq\frac{\|B\hat{\boldsymbol{c}} - \boldsymbol{b}\|_2}{\|B\boldsymbol{c} - \boldsymbol{b}\|_2}
\le 
\frac{\|S\|_2}{\sigma_{\min}(SU)},
\end{equation}
where $B = UH$ is the polar decomposition. We also have
\begin{equation}
1\leq\frac{\|B\hat{\boldsymbol{c}} - \boldsymbol{b}\|_2}{\|B\boldsymbol{c} - \boldsymbol{b}\|_2}
\le 
\kappa_2(\widetilde{S}U),
\end{equation}
where $\widetilde{U}\widetilde{H} = [B\ \boldsymbol{b}] \in \mathbb{R}^{n \times (r+1)}$ is the polar decomposition, and 
$\kappa_2(\widetilde{S}U) = \frac{\sigma_{\max}(\widetilde{S}U)}{\sigma_{\min}(\widetilde{S}U)}.$

